pub fn fixture_source_root() -> PathBuf {
    let manifest = Path::new(env!("CARGO_MANIFEST_DIR"));
    // Standalone repo layout: fixture data is bundled at the crate root.
    let repo_local = manifest.join("test-fixtures/memory-workspace-fixture");
    if repo_local.is_dir() {
        return repo_local;
    }
    // In-tree layout: the crate lives under `<repo>/crates/memory-fixtures`
    // and shares `<repo>/test-fixtures` with its sibling crates.
    manifest.join("../../test-fixtures/memory-workspace-fixture")
}

